<?php use Luna\Core\Csrf; use Luna\Core\View; ?>
<div class="page-actions"><a class="button" href="/imports">← Importazioni</a><div><?php if (in_array($batch['status'], ['READY','ERROR'], true)): ?><form method="post" action="/imports/<?= (int) $batch['id'] ?>/commit" class="inline-form" data-confirm="Confermare l’importazione nel database operativo?"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><button class="button primary">Conferma importazione</button></form><?php elseif (in_array($batch['status'], ['COMPLETED','COMPLETED_WITH_ERRORS'], true)): ?><form method="post" action="/imports/<?= (int) $batch['id'] ?>/rollback" class="inline-form" data-confirm="Annullare tutti i record riconducibili a questo lotto?"><input type="hidden" name="_token" value="<?= View::e(Csrf::token()) ?>"><button class="button danger">Rollback lotto</button></form><?php endif; ?></div></div>
<section class="metric-grid compact"><article class="metric"><span>Stato</span><strong class="small-text"><?= View::e($batch['status']) ?></strong></article><article class="metric"><span>Tipo</span><strong class="small-text"><?= View::e($batch['import_type']) ?></strong></article><article class="metric"><span>Righe</span><strong><?= (int) $batch['total_rows'] ?></strong></article><article class="metric"><span>Importate</span><strong><?= (int) $batch['imported_rows'] ?></strong></article><article class="metric danger"><span>Errori</span><strong><?= (int) $batch['error_rows'] ?></strong></article></section>
<?php if ($batch['error_message']): ?><div class="alert alert-error"><?= View::e($batch['error_message']) ?></div><?php endif; ?>
<section class="card table-wrap"><table><thead><tr><th>Riga</th><th>Anteprima normalizzata</th><th>Stato</th><th>Errore</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= (int) $row['source_row_number'] ?></td><td><pre class="json-preview"><?= View::e(json_encode($row['data'], JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES)) ?></pre></td><td><span class="badge"><?= View::e($row['status']) ?></span></td><td class="danger-text"><?= View::e($row['error_message']) ?></td></tr><?php endforeach; ?><?php if (!$rows): ?><tr><td colspan="4" class="muted">Nessuna riga rilevata.</td></tr><?php endif; ?></tbody></table></section>
